extern u8 *D_03004010;

void sub_08012200(u8 *player) {
    u32 i = 0;
    u8 *game = D_03004010;
    u16 *timer = (u16 *)(player + 0x4A);
    do {
        *timer -= game[7];
        if ((s16)*timer < 0) *timer = 0;
        ++timer;
        ++i;
    } while (i <= 9);
}

